import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { findTeamHandler } from "../handlers/findTeamHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof findTeamHandler>>;

export function useFindTeam(
  username: string,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["findTeam", username],
    queryFn: () => findTeamHandler(username),
    ...options,
  });
}
